  quiz: [
    { q: "Che cos'era la Confederazione germanica?", options: ["Uno Stato unitario", "Unione di Stati sovrani presieduta dall'Austria", "Una repubblica", "Un'alleanza solo prussiana"], answer: 1, why: "Coordinava Stati sovrani e non possedeva un governo nazionale.", recover: "Rivedi la lezione 1.", lesson: "germania-prima" },
    { q: "Perché lo Zollverein non basta a spiegare l'unità?", options: ["Integrò mercati ma non eliminò sovranità", "Creò subito l'imperatore", "Comprendeva l'Austria", "Abolì gli eserciti"], answer: 0, why: "L'integrazione rafforzò la Prussia, ma la decisione politica restava aperta.", recover: "Distingui mercato e Stato.", lesson: "germania-prima" },
    { q: "Perché fallì Francoforte?", options: ["Non scrisse una costituzione", "Non ebbe forza per imporla ai principi", "Scelse la repubblica austriaca", "Fu sciolta da Bismarck"], answer: 1, why: "Deliberò una costituzione, ma dipendeva dai poteri dinastici.", recover: "Riapri la fonte.", lesson: "germania-prima" },
    { q: "Qual era il centro del conflitto prussiano?", options: ["La bandiera", "Bilancio e controllo dell'esercito", "Le colonie", "Il voto femminile"], answer: 1, why: "Camera e Corona si scontrarono sulle spese militari.", recover: "Rileggi la lezione 2.", lesson: "crisi-prussiana" },
    { q: "Che cosa NON prova il discorso del 1862?", options: ["Il conflitto con i liberali", "La centralità dell'esercito", "Un piano dettagliato delle tre guerre", "La preferenza per la forza statale"], answer: 2, why: "La sequenza futura è una ricostruzione retrospettiva.", recover: "Distingui fonte e mito.", lesson: "crisi-prussiana" },
    { q: "Perché i ducati non furono un puro pretesto?", options: ["Esistevano problemi dinastici, giuridici e nazionali", "La Danimarca invase Berlino", "Non c'erano abitanti", "Erano già prussiani"], answer: 0, why: "Status e nazionalismi concorrenti rendevano reale la crisi.", recover: "Rivedi la lezione 3.", lesson: "ducati" },
    { q: "Che cosa stabilì Gastein?", options: ["Distruzione dell'Austria", "Amministrazione separata dei ducati", "Alleanza franco-prussiana", "Nascita del Reich"], answer: 1, why: "Divise l'amministrazione senza risolvere la sovranità.", recover: "Segui 1864-1865.", lesson: "ducati" },
    { q: "Che cosa contribuì alla vittoria del 1866?", options: ["Una sola arma", "Comando, logistica, ferrovie e tecnologia", "L'intervento francese", "La resa italiana"], answer: 1, why: "La vittoria derivò da una combinazione organizzativa e militare.", recover: "Rivedi la lezione 4.", lesson: "guerra-austria" },
    { q: "Perché la pace con l'Austria fu moderata?", options: ["Per una futura collaborazione", "La Prussia aveva perso", "L'Austria entrò nel Reich", "Lo impose l'Italia"], answer: 0, why: "L'obiettivo era escludere Vienna senza farne un nemico permanente.", recover: "Apri Nikolsburg.", lesson: "guerra-austria" },
    { q: "Che cosa fece Bismarck al dispaccio?", options: ["Inventò l'ambasciatore", "Lo abbreviò rendendolo tagliente", "Dichiarò guerra", "Lo mantenne segreto"], answer: 1, why: "Omissioni e montaggio cambiarono il tono.", recover: "Confronta le versioni.", lesson: "francia-reich" },
    { q: "Chi dichiarò guerra nel luglio 1870?", options: ["La Francia", "La Prussia", "L'Austria", "La Spagna"], answer: 0, why: "La scelta francese completò l'escalation.", recover: "Distingui provocazione e decisione.", lesson: "francia-reich" },
    { q: "Quando fu proclamato il Reich?", options: ["18 gennaio 1871", "3 luglio 1866", "30 settembre 1862", "10 maggio 1871"], answer: 0, why: "Guglielmo I fu proclamato a Versailles.", recover: "Rivedi la timeline.", lesson: "francia-reich" },
    { q: "Quale potere aveva il Reichstag?", options: ["Nessuno", "Approvava leggi e bilancio", "Nominava l'imperatore", "Comandava l'esercito"], answer: 1, why: "Era necessario alla legislazione pur non formando il governo.", recover: "Riapri il diagramma.", lesson: "costituzione-reich" },
    { q: "Da chi dipendeva il cancelliere?", options: ["Dal Reichstag", "Dall'imperatore", "Da Vienna", "Dagli elettori direttamente"], answer: 1, why: "La responsabilità dell'esecutivo era monarchica.", recover: "Distingui elezione e governo.", lesson: "costituzione-reich" },
    { q: "Effetto del Kulturkampf?", options: ["Scomparsa del Zentrum", "Rafforzamento cattolico", "Fine del federalismo", "Conversione di Bismarck"], answer: 1, why: "La repressione aumentò la mobilitazione del Zentrum.", recover: "Rivedi la lezione 6.", lesson: "costituzione-reich" },
    { q: "La legge antisocialista impedì ogni candidatura?", options: ["Sì", "No, vietò organizzazioni e stampa", "Solo in Baviera", "Solo dopo il 1890"], answer: 1, why: "La presenza elettorale rimase possibile.", recover: "Rileggi la lezione 7.", lesson: "stato-sociale" },
    { q: "Quale assicurazione arrivò per prima?", options: ["Malattia nel 1883", "Vecchiaia nel 1871", "Disoccupazione nel 1862", "Maternità nel 1848"], answer: 0, why: "La sequenza iniziò con la malattia.", recover: "Rivedi la cronologia.", lesson: "stato-sociale" },
    { q: "Perché protezione e repressione erano complementari?", options: ["Rafforzavano lo Stato e indebolivano la SPD", "Erano socialiste", "Non furono applicate", "Abolivano la monarchia"], answer: 0, why: "Appartenevano allo stesso progetto conservatore.", recover: "Confronta le fonti.", lesson: "stato-sociale" },
    { q: "Obiettivo della controassicurazione?", options: ["Alleanza franco-russa", "Neutralità russa e prevenzione dei due fronti", "Distruzione dell'Austria", "Conquista britannica"], answer: 1, why: "Bismarck voleva legare Vienna senza perdere la Russia.", recover: "Apri la rete.", lesson: "equilibrio-eredita" },
    { q: "Quale giudizio è più preciso?", options: ["Bismarck creò tutto da solo", "L'unità fu automatica", "Trasformò condizioni precedenti in unità a guida monarchico-prussiana", "Il Reich fu subito parlamentare"], answer: 2, why: "La tesi integra strutture, scelte e forma del risultato.", recover: "Costruisci la tesi finale.", lesson: "equilibrio-eredita" }
  ]
